import{_ as e,o,c as t,a2 as r}from"./chunks/framework.CiKk3sJz.js";const m=JSON.parse('{"title":"漫画 · 第 4 话 Grid：先分格，再落子","description":"","frontmatter":{},"headers":[],"relativePath":"comics/css/EP.04-grid.md","filePath":"comics/css/EP.04-grid.md","lastUpdated":1792579602000}'),i={name:"comics/css/EP.04-grid.md"};function d(l,a,s,n,c,u){return o(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="漫画-·-第-4-话-grid-先分格-再落子" tabindex="-1">漫画 · 第 4 话 Grid：先分格，再落子 <a class="header-anchor" href="#漫画-·-第-4-话-grid-先分格-再落子" aria-label="Permalink to &quot;漫画 · 第 4 话 Grid：先分格，再落子&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/css/04-grid">docs/css/04-grid.md</a> ｜ 原画：<a href="./EP.04-grid.svg">EP.04-grid.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话主角。写了两列 <code>1fr 1fr</code>，左列却被一条超长 SKU 编码顶成 3:1。</li><li><strong>标签君</strong>：HTML5 结构师，用 <code>grid-template-areas</code> 演示&quot;ASCII 地图即页面骨架&quot;。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p><code>1fr 1fr</code> 不等分，根因和 Flex 的 <code>min-width: auto</code> 同源——fr 轨道的下限默认是内容的 min-content。像素酱用 <code>minmax(0, 1fr)</code> 钳住下限，再用 <code>repeat(auto-fit, minmax(240px, 1fr))</code> 画出了一条零媒体查询的响应式画廊。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>无空格的 SKU 字符串没有断行点，min-content 就是整串宽度。<strong>fr 轨道的最小尺寸默认是 auto（不小于内容 min-content）</strong>，于是&quot;写好的 1fr 1fr&quot;被内容顶成了 3:1。这与 Flex 的自动最小尺寸坑同源，Grid 里的修复方式是把轨道写成 <code>minmax(0, 1fr)</code>，或给内容容器加 <code>min-width: 0</code> + 截断。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>Grid 是<strong>二维</strong>布局：<code>grid-template-columns/rows</code> 划分行 × 列轨道，项目落进格子。<code>grid-template-areas</code> 用一串字符串画出页面地图——<code>&quot;header header&quot; &quot;nav main&quot; &quot;status status&quot;</code> 看一眼就知道布局长什么样；窄屏重排只需改这一个字符串，所有落位规则零改动。网格线从 1 编号，负数从末尾倒数（-1 = 最后一条线），<code>span N</code> 表示跨 N 格。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p><code>repeat(auto-fit, minmax(240px, 1fr))</code> 逐词翻译：重复（自动适配列数，每列最小 240px、最大 1 份）。<strong>auto-fit 折叠空轨道</strong>，项目被拉宽铺满整行；<strong>auto-fill 保留空轨道</strong>，列宽稳定但不拉伸——列表页用 auto-fill，横幅用 auto-fit。另外项目数量动态时记得设 <code>grid-auto-rows</code>，否则隐式行按内容自适应，&quot;等高画廊&quot;会参差不齐。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>Flex 管一维流，Grid 管二维格；选型先问&quot;几根轴&quot;。</li><li>1fr 下限是 min-content，严格等分写 <code>minmax(0, 1fr)</code>。</li><li>auto-fit 折叠空轨铺满，auto-fill 保留空轨列宽稳；动态行数记得设 <code>grid-auto-rows</code>。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：容器里只有 3 张卡片、一行能装 6 列时，<code>auto-fill</code> 与 <code>auto-fit</code> 各是什么表现？</p><p><strong>答</strong>：<code>auto-fill</code> 优先造空轨道——右侧留 3 列看不见的空列占位，卡片不拉伸；<code>auto-fit</code> 把空轨道折叠为 0，剩余空间分给实轨道，3 张卡片拉宽铺满整行。做&quot;列宽稳定&quot;的列表页用 auto-fill，做&quot;永远铺满&quot;的横幅用 auto-fit。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>轨道尺寸：fr、minmax、auto-fit vs auto-fill 对比：<a href="./../../examples/css/04-grid/index-01-track-units.html">examples/css/04-grid/</a></li><li>areas 页面骨架 + 网格线定位与 span：<a href="./../../examples/css/04-grid/index-02-areas-lines-span.html">index-02-areas-lines-span.html</a></li><li>无媒体查询响应式画廊 + dense 密集流：<a href="./../../examples/css/04-grid/index-04-responsive-gallery.html">index-04-responsive-gallery.html</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>同一套页面，手机上是单列、桌面端是三栏——第 5 话《响应式布局》，媒体查询与移动优先的正确姿势。</p>',22)])])}const f=e(i,[["render",d]]);export{m as __pageData,f as default};
